  const script=doc.createElement('script');script.id='salu-premium-js';script.defer=true;script.src='salu-premium.js?v='+VERSION;head.appendChild(script);
  const theme=doc.querySelector('meta[name="theme-color"]');if(theme)theme.setAttribute('content','#1a34b0');
  const hubMenu=doc.getElementById('hubMenu');
